// ===============================================================================
// DAEMIND SRE - HUB ROTEADOR UNIVERSAL E FALLBACK DE E-COMMERCE & MARKETPLACES
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

let origem = ($json.query?.origem || body.origem || 'E-Commerce Universal').toString();
let rawPhone = (body.cliente?.telefone || body.customer?.phone || body.phone || body.whatsapp || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (body.cliente?.nome || body.customer?.name || body.name || 'Cliente').trim();
const clienteEmail = (body.cliente?.email || body.customer?.email || body.email || '').trim().toLowerCase();
const numeroPedido = parseInt(body.numero || body.id || Date.now(), 10);
const valorTotal = parseFloat(body.valor_total || body.total || 0);

const dedupHash = crypto.createHash('sha256').update(`${origem}_${numeroPedido}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    origem: origem,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    valor_total: valorTotal
  }
}];
